StructuredTextModel.Text:
//-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
//	NAME:						Average
//	CREATOR:					Daniel Årvik
// REQUIREMENTS: 		NX CPU
// 
//-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
//  VERSION LOG:
//	VERSION			DATE					SIGN						DESCRIPTION
//	1.0.0					2023-03-06			Daniel Årvik				Initial Release
//	2.0.0					2025-04-02			William Veim			Rework
//	2.0.1					2025-04-10			Ruben Byman			Removed retain of buffer, and minor bug fixes
//	2.1.0					2025-11-17			Ruben Byman			Rework and translation
//
//===============================================================================================================================
//
//		BESKRIVELSE:
//		Excecute avergae based on interval time and number of values.
//
//===============================================================================================================================

// Variable control
TimeSinceTrigger := ADD_TIME(In1 := TimeSinceTrigger, In2 := GetMyTaskInterval());
Cfg_SamplingInterval:=LIMIT(MN:=UINT#10, In:=Cfg_SamplingInterval, MX:=UINT#10000);
Cfg_NumberOfValues:=LIMIT(MN:=UINT#1, In:=Cfg_NumberOfValues, MX:=DINT_TO_UINT(UPPER_BOUND(AverageBuffer,1)));

// Average control/calculation
IF TimeSinceTrigger >= NanoSecToTime(Cfg_SamplingInterval*1000000) THEN
	
	TimeSinceTrigger:=TIME#0ms;
	SumValues:=0;
	
	// FIFO (move all values
	IF NumberUsed>1 THEN
		FOR Index := NumberUsed-1 TO 0 BY -1 DO
			AverageBuffer[Index+1]:=AverageBuffer[Index];
		END_FOR;
	END_IF;
	
	//Moves new value to index 0
	AverageBuffer[0]:= Inp_Value;
	
	//Sum all values (numer of values used)
	IF NumberUsed>1 THEN
	FOR Index :=0 TO NumberUsed - 1 DO
		SumValues:=SumValues+AverageBuffer[Index];
	END_FOR;
	ELSE
		SumValues:=AverageBuffer[0];
	END_IF;
	
	// Calculates average value
	Out_Average := LREAL_TO_REAL(SumValues / UINT_TO_REAL(NumberUsed));
	
	// Control of number of values used
	IF NumberUsed < Cfg_NumberOfValues THEN
		 Inc(NumberUsed);
	ELSIF Inp_Reset THEN
		Clear(NumberUsed);
	ELSE
		NumberUsed:=Cfg_NumberOfValues;
	END_IF;
	
END_IF;
